package printing

// report_test.go — the golden tests for the report renderer.
//
// WHAT IS ASSERTED, AND WHY IT IS NOT A SCREENSHOT. Every test here checks the
// GENERATED BYTES against a committed golden and, separately, the TEXT EXTRACTED
// from those bytes. The bytes catch a moved rule or a changed font; the extracted
// text is what makes a failure readable ("page 3 does not say Page 3 of 3"
// instead of "byte 4471 differs"). A screenshot comparison could not tell a right
// total from a wrong one, which is the only thing that matters on a statement an
// accountant signs.
//
// REGENERATING THE GOLDENS. When a layout change is INTENDED:
//
//	cd backend && PRINTING_UPDATE_GOLDEN=1 go test ./internal/printing/ -run TestAReport -count=1
//	cd backend && PRINTING_UPDATE_GOLDEN=1 go test ./internal/printing/ -run 'Report|LedgerName|DayBook|TrialBalance' -count=1
//
// then READ THE DIFF of testdata/report_*.txt before committing — the .txt golden
// exists precisely so that the review step is "the words on the paper changed
// like this", not "3kB of binary changed". Regenerating to make a red test green
// without reading that diff is how a wrong figure gets committed as the new
// expectation.

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"

	"github.com/shopspring/decimal"
)

// ---------------------------------------------------------------------------
// golden-file plumbing
// ---------------------------------------------------------------------------

// reportUpdateGolden is driven by an ENVIRONMENT VARIABLE and not by a test flag
// on purpose: this package holds three renderers written by three hands, and a
// second flag.Bool("update", ...) registered in a sibling _test.go would panic
// the whole test binary at init with "flag redefined". An env var composes.
func reportUpdateGolden() bool { return os.Getenv("PRINTING_UPDATE_GOLDEN") == "1" }

// reportGolden compares got against testdata/<name>.pdf and the text extracted
// from it against testdata/<name>.txt, and returns the extracted text so a test
// can go on to assert on individual lines.
func reportGolden(t *testing.T, name string, got []byte) []string {
	t.Helper()

	lines, err := ExtractText(got)
	if err != nil {
		t.Fatalf("the %s we just produced is not a readable PDF, so it would not open for the accountant it was printed for: %v", name, err)
	}
	for i, l := range lines {
		if strings.ContainsAny(l, "\r\n") {
			t.Fatalf("drawn string %d of %s contains a line break (%q); the .txt golden is one drawn string per line and would silently disagree with the PDF", i, name, l)
		}
	}
	text := strings.Join(lines, "\n") + "\n"

	pdfPath := filepath.Join("testdata", "report_"+name+".pdf")
	txtPath := filepath.Join("testdata", "report_"+name+".txt")

	if reportUpdateGolden() {
		if err := os.MkdirAll("testdata", 0o755); err != nil {
			t.Fatalf("cannot create testdata: %v", err)
		}
		if err := os.WriteFile(pdfPath, got, 0o644); err != nil {
			t.Fatalf("cannot write %s: %v", pdfPath, err)
		}
		if err := os.WriteFile(txtPath, []byte(text), 0o644); err != nil {
			t.Fatalf("cannot write %s: %v", txtPath, err)
		}
		t.Logf("regenerated %s and %s — READ THE .txt DIFF before committing", pdfPath, txtPath)
		return lines
	}

	wantPDF, err := os.ReadFile(pdfPath)
	if err != nil {
		t.Fatalf("the golden %s is missing, so this test proves nothing; regenerate with PRINTING_UPDATE_GOLDEN=1 and review the diff: %v", pdfPath, err)
	}
	wantTXT, err := os.ReadFile(txtPath)
	if err != nil {
		t.Fatalf("the golden %s is missing: %v", txtPath, err)
	}

	if text != string(wantTXT) {
		t.Errorf("the WORDS PRINTED on %s changed.\n--- what the signed-off document says ---\n%s\n--- what this build prints ---\n%s",
			name, string(wantTXT), text)
	}
	if !bytes.Equal(got, wantPDF) {
		t.Errorf("the PRINTED BYTES of %s changed (%d bytes now, %d before; first difference at byte %d). Something moved on the page: a rule, a font, a column edge or a figure.",
			name, len(got), len(wantPDF), reportFirstDiff(got, wantPDF))
	}
	return lines
}

func reportFirstDiff(a, b []byte) int {
	n := len(a)
	if len(b) < n {
		n = len(b)
	}
	for i := 0; i < n; i++ {
		if a[i] != b[i] {
			return i
		}
	}
	return n
}

// ---------------------------------------------------------------------------
// reading our own output back, per page
// ---------------------------------------------------------------------------

// reportTextOp is one drawn string with the geometry it was drawn at, recovered
// from the content stream. Page.Text writes every string in exactly one shape,
// which is what makes this possible; it is the same reason ExtractText exists.
type reportTextOp struct {
	font     string
	size     float64
	x, y     float64
	text     string
	pageIdx  int
	rawIndex int
}

// reportPagesText returns the drawn strings per page, in page order. The content
// streams are the only stream objects this writer emits and their object numbers
// increase with the page index (see pdf.go), so object order IS page order.
func reportPagesText(t *testing.T, pdf []byte) [][]reportTextOp {
	t.Helper()
	objs, err := parseObjects(pdf)
	if err != nil {
		t.Fatalf("the document is not readable: %v", err)
	}
	var pages [][]reportTextOp
	for _, o := range objs {
		content, ok := streamBody(pdf, o)
		if !ok {
			continue
		}
		idx := len(pages)
		pages = append(pages, reportParseTextOps(t, content, idx))
	}
	return pages
}

// reportParseTextOps parses "BT /F1 8.5 Tf 1 0 0 1 x y Tm (s) Tj ET" operators.
//
// THE strconv.ParseFloat CALLS BELOW ARE GEOMETRY, NOT MONEY. They read a font
// size and an (x,y) in POINTS back out of a content stream so that a test can
// prove a cell stayed inside its column. Every AMOUNT in these tests is a
// decimal.Decimal formatted with FormatMoney and compared as a STRING; no figure
// on any of these documents passes through a float64 at any point.
func reportParseTextOps(t *testing.T, content []byte, pageIdx int) []reportTextOp {
	t.Helper()
	var out []reportTextOp
	s := string(content)
	for _, line := range strings.Split(s, "\n") {
		if !strings.HasPrefix(line, "BT /") {
			continue
		}
		open := strings.IndexByte(line, '(')
		if open < 0 {
			t.Fatalf("a text operator with no string literal: %q", line)
		}
		head := strings.Fields(line[:open])
		// head: BT /F1 8.5 Tf 1 0 0 1 x y Tm
		if len(head) != 11 || head[3] != "Tf" || head[10] != "Tm" {
			t.Fatalf("a text operator this test cannot parse (page.go changed shape?): %q", line)
		}
		size, err := strconv.ParseFloat(head[2], 64)
		if err != nil {
			t.Fatalf("unparseable font size in %q", line)
		}
		x, err := strconv.ParseFloat(head[8], 64)
		if err != nil {
			t.Fatalf("unparseable x in %q", line)
		}
		y, err := strconv.ParseFloat(head[9], 64)
		if err != nil {
			t.Fatalf("unparseable y in %q", line)
		}
		text, _, err := readLiteral([]byte(line), open)
		if err != nil {
			t.Fatalf("unreadable string literal in %q: %v", line, err)
		}
		out = append(out, reportTextOp{
			font: strings.TrimPrefix(head[1], "/"), size: size,
			x: x, y: y, text: text, pageIdx: pageIdx, rawIndex: len(out),
		})
	}
	return out
}

func reportPageStrings(ops []reportTextOp) []string {
	out := make([]string, 0, len(ops))
	for _, o := range ops {
		out = append(out, o.text)
	}
	return out
}

func reportContains(ops []reportTextOp, want string) bool {
	for _, o := range ops {
		if o.text == want {
			return true
		}
	}
	return false
}

