// reportThreePageFixture is long enough to need three sheets, which is what makes
// the repeated furniture and "Page N of M" testable. 120 rows at the body height
// this geometry gives is 56 + 56 + 8.
func reportThreePageFixture() ReportTable {
	t := ReportTable{
		Title:    "Outstandings - Receivables",
		Subtitle: "as on 31-Dec-2026",
		Company:  reportTestCompany(),
		Columns: []Column{
			{Header: "Party", Align: AlignLeft, Width: 4},
			{Header: "Bill No.", Align: AlignLeft, Width: 2},
			{Header: "Pending", Align: AlignRight, Width: 1.5},
		},
		Overrides: TemplateOverrides{
			HeaderLines: []string{
				"14, Nariman Point, Mumbai 400021 - GSTIN 27AABCS1429B1ZX",
				"Statement generated from the books of account",
			},
			FooterLines: []string{"Subject to confirmation by the parties named above."},
		},
	}
	total := decimal.Zero
	for i := 1; i <= 120; i++ {
		amt := decimal.NewFromInt(int64(1000 + i))
		total = total.Add(amt)
		t.Rows = append(t.Rows, Row{Cells: []string{
			fmt.Sprintf("Debtor %03d Enterprises", i),
			fmt.Sprintf("SL/2026-27/%04d", i),
			FormatMoney(amt),
		}})
	}
	t.Footer = []Row{{Cells: []string{"Total outstanding", "", FormatMoney(total)}, Bold: true, RuleAbove: true, RuleBelow: true}}
	return t
}

