// the golden tests
// ---------------------------------------------------------------------------

func TestATrialBalancePrintsItsGroupTreeAndTotalsExactlyAsSignedOff(t *testing.T) {
	got, err := RenderReport(reportTrialBalanceFixture())
	if err != nil {
		t.Fatalf("the Trial Balance would not print: %v", err)
	}
	lines := reportGolden(t, "trial_balance", got)

	for _, want := range []string{
		"Trial Balance", "as on 31-Mar-2027", "Sundaram Traders Private Limited",
		"Particulars", "Debit", "Credit",
		"Duties & Taxes", "Output CGST @ 9%",
		"Grand Total", "7,41,456.78", "1,23,456.78", "Page 1 of 1",
	} {
		found := false
		for _, l := range lines {
			if l == want {
				found = true
				break
			}
		}
		if !found {
			t.Errorf("the Trial Balance does not print %q anywhere; an accountant reading this statement would not find it", want)
		}
	}

	// The tree: a group heading sits to the LEFT of the ledgers under it, and a
	// second-level ledger sits to the left of nothing. A Trial Balance whose
	// indents collapsed reads as a flat list and its subtotals stop making sense.
	ops := reportPagesText(t, got)[0]
	xOf := func(s string) float64 {
		for _, o := range ops {
			if o.text == s {
				return o.x
			}
		}
		t.Fatalf("%q is not on the page at all", s)
		return 0
	}
	group, level1, level2 := xOf("Current Liabilities"), xOf("Sundry Creditors"), xOf("Output CGST @ 9%")
	if !(group < level1 && level1 < level2) {
		t.Errorf("the group tree is not indented: %q at x=%s, %q at x=%s, %q at x=%s — a Balance Sheet printed flat cannot be read as a tree",
			"Current Liabilities", fmtNum(group), "Sundry Creditors", fmtNum(level1), "Output CGST @ 9%", fmtNum(level2))
	}

	// Bold is not decoration: a total set in the body face is indistinguishable
	// from one more ledger line.
	for _, o := range ops {
		if o.text == "Grand Total" && o.font != HelveticaBold.resourceName() {
			t.Errorf("the Grand Total is set in %s, not in bold, so it does not read as a total", o.font)
		}
	}
}

func TestADayBookPrintsLandscapeSoTheNarrationColumnIsNotClipped(t *testing.T) {
	tbl := reportDayBookFixture()
	got, err := RenderReport(tbl)
	if err != nil {
		t.Fatalf("the Day Book would not print: %v", err)
	}
	lines := reportGolden(t, "daybook_landscape", got)

	if !bytes.Contains(got, []byte("/MediaBox [0 0 "+fmtNum(A4Landscape.Width)+" "+fmtNum(A4Landscape.Height)+"]")) {
		t.Errorf("ReportTable.Landscape did not reach the /MediaBox, so a seven-column Day Book printed on a portrait sheet")
	}
	for _, want := range []string{"Narration", "Invoice for 10 switchgear panels ex-Bhiwandi", "Total for the period", "2,36,000.22"} {
		found := false
		for _, l := range lines {
			if l == want {
				found = true
				break
			}
		}
		if !found {
			t.Errorf("the Day Book does not print %q; the entry it belongs to is unreadable without it", want)
		}
	}
	reportAssertNothingOverflowsItsColumn(t, tbl, got)
	reportAssertNoFurnitureIsClippedByTheEdgeOfTheSheet(t, tbl, got)
}

func TestEveryPageOfAThreePageReportRepeatsItsHeadersAndSaysWhichSheetItIs(t *testing.T) {
	tbl := reportThreePageFixture()
	got, err := RenderReport(tbl)
	if err != nil {
		t.Fatalf("the Outstandings statement would not print: %v", err)
	}
	reportGolden(t, "three_pages", got)

	pages := reportPagesText(t, got)
	if len(pages) != 3 {
		t.Fatalf("the 120-row Outstandings statement came out on %d sheets, not 3; this fixture exists to prove the furniture repeats, and it cannot with %d", len(pages), len(pages))
	}

	for i, ops := range pages {
		for _, want := range []string{
			"Sundaram Traders Private Limited",
			"14, Nariman Point, Mumbai 400021 - GSTIN 27AABCS1429B1ZX",
			"Outstandings - Receivables",
			"as on 31-Dec-2026",
			"Party", "Bill No.", "Pending",
		} {
			if !reportContains(ops, want) {
				t.Errorf("page %d of the Outstandings statement does not carry %q. A reader handed sheet %d alone cannot tell whose books it is or which column is the amount — that is what makes a multi-page statement unusable.", i+1, want, i+1)
			}
		}
		stamp := fmt.Sprintf("Page %d of 3", i+1)
		if !reportContains(ops, stamp) {
			t.Errorf("page %d does not say %q, so a reader cannot tell that a sheet is missing from the staple. It prints: %v", i+1, stamp, reportPageStrings(ops))
		}
	}

	// The totals belong on the last sheet ONLY: a "Total outstanding" on page 1
	// would be read as the total of page 1 and reconciled against.
	for i, ops := range pages {
		has := reportContains(ops, "Total outstanding")
		if i == len(pages)-1 && !has {
			t.Errorf("the last sheet carries no total, so the Outstandings statement never states what is outstanding")
		}
		if i != len(pages)-1 && has {
			t.Errorf("sheet %d carries the grand total although it is not the last sheet; a reader would take a mid-statement figure for the closing one", i+1)
		}
	}
	// And Overrides.FooterLines are the closing note, on the last sheet only.
	if !reportContains(pages[2], "Subject to confirmation by the parties named above.") {
		t.Errorf("the closing note from Overrides.FooterLines is missing from the last sheet")
	}

	reportAssertNothingOverflowsItsColumn(t, tbl, got)
	reportAssertNoFurnitureIsClippedByTheEdgeOfTheSheet(t, tbl, got)
}

func TestAReportWithNoEntriesStillPrintsOnePageSayingSo(t *testing.T) {
	tbl := ReportTable{
		Title:    "Day Book",
		Subtitle: "15-Aug-2026 to 15-Aug-2026",
		Company:  reportTestCompany(),
		Columns: []Column{
			{Header: "Date", Align: AlignLeft, Width: 1},
			{Header: "Particulars", Align: AlignLeft, Width: 4},
			{Header: "Debit", Align: AlignRight, Width: 1.5},
			{Header: "Credit", Align: AlignRight, Width: 1.5},
		},
	}
	got, err := RenderReport(tbl)
	if err != nil {
		t.Fatalf("a report with no entries must still print a page that says so, and instead it failed: %v", err)
	}
	if len(got) == 0 {
		t.Fatalf("a report with no entries produced a zero-byte file, which downloads as a broken document and sends somebody looking for a fault that is not there")
	}
	lines := reportGolden(t, "empty", got)

	pages := reportPagesText(t, got)
	if len(pages) != 1 {
		t.Errorf("an empty report came out on %d pages", len(pages))
	}
	if !reportContains(pages[0], reportEmptyNotice) {
		t.Errorf("the empty Day Book does not say %q, so a reader cannot tell an empty period from a failed print. It prints: %v", reportEmptyNotice, lines)
	}
	if !reportContains(pages[0], "Page 1 of 1") {
		t.Errorf("the empty Day Book is not paginated")
	}
	if !reportContains(pages[0], "Particulars") {
		t.Errorf("the empty Day Book dropped its column headers, so it does not read as the report it is")
	}
}

func TestALongLedgerNameWrapsInsteadOfRunningIntoTheAmountColumn(t *testing.T) {
	const long = "Maharashtra State Electricity Distribution Company Limited - Bhiwandi Circle Office Deposit A/c"
	tbl := ReportTable{
		Title:    "Trial Balance",
		Subtitle: "as on 31-Mar-2027",
		Company:  reportTestCompany(),
		Columns: []Column{
			{Header: "Particulars", Align: AlignLeft, Width: 2},
			{Header: "Debit", Align: AlignRight, Width: 1},
			{Header: "Credit", Align: AlignRight, Width: 1},
		},
		Rows: []Row{
			{Cells: []string{long, reportMoney("125000"), ""}, Indent: 1},
			{Cells: []string{"Cash-in-Hand", reportMoney("2500.50"), ""}, Indent: 1},
		},
		Footer: []Row{{Cells: []string{"Grand Total", reportMoney("127500.50"), ""}, Bold: true, RuleAbove: true}},
	}
	got, err := RenderReport(tbl)
	if err != nil {
		t.Fatalf("a long ledger name must wrap, and instead the report would not print: %v", err)
	}
	lines := reportGolden(t, "long_ledger_name", got)

	// The name is not on the page in one piece: it was wrapped. And every piece of
	// it is still there — a wrapped name that lost its tail is a different ledger.
	joined := strings.Join(lines, " ")
	if reportContains(reportPagesText(t, got)[0], long) {
		t.Errorf("the 94-character ledger name was drawn as one line, so it runs across the Debit and Credit columns and the amount beside it is unreadable")
	}
	for _, word := range strings.Fields(long) {
		if !strings.Contains(joined, word) {
			t.Errorf("wrapping the ledger name lost the word %q; the account printed is not the account in the books", word)
		}
	}
	reportAssertNothingOverflowsItsColumn(t, tbl, got)
	reportAssertNoFurnitureIsClippedByTheEdgeOfTheSheet(t, tbl, got)
}

func TestALabelTooLongToWrapIsMarkedWithAnEllipsisNotSilentlyClipped(t *testing.T) {
	long := strings.Repeat("Bhiwandi Circle Office Security Deposit Account ", 12)
	tbl := ReportTable{
		Title:   "Trial Balance",
		Company: reportTestCompany(),
		Columns: []Column{
			{Header: "Particulars", Align: AlignLeft, Width: 1},
			{Header: "Debit", Align: AlignRight, Width: 1},
		},
		Rows: []Row{{Cells: []string{long, reportMoney("1000")}}},
	}
	got, err := RenderReport(tbl)
	if err != nil {
		t.Fatalf("an absurdly long label must be abbreviated, not refused: %v", err)
	}
	ops := reportPagesText(t, got)[0]
	var body []reportTextOp
	for _, o := range ops {
		if o.size == reportBodySize {
			body = append(body, o)
		}
	}
	if len(body) != reportMaxCellLines+1 { // the label's lines plus the figure
		t.Fatalf("the over-long label was drawn on %d lines; the cap is %d lines plus the amount, and an uncapped row can grow taller than the sheet it is printed on", len(body)-1, reportMaxCellLines)
	}
	last := body[reportMaxCellLines-1].text
	if !strings.HasSuffix(last, reportEllipsis) {
		t.Errorf("the abbreviated ledger name ends %q with no %q, so a reader cannot tell the name was cut and will take the truncated name for the real one", last, reportEllipsis)
	}
	reportAssertNothingOverflowsItsColumn(t, tbl, got)
	reportAssertNoFurnitureIsClippedByTheEdgeOfTheSheet(t, tbl, got)
}

func TestADateTooWideForItsColumnIsAbbreviatedNotSplitAcrossTwoLines(t *testing.T) {
	tbl := ReportTable{
		Title:   "Day Book",
		Company: reportTestCompany(),
		Columns: []Column{
			{Header: "Date", Align: AlignLeft, Width: 1}, // one twelfth of the sheet
			{Header: "Particulars", Align: AlignLeft, Width: 10},
			{Header: "Debit", Align: AlignRight, Width: 1.5},
		},
		Rows: []Row{{Cells: []string{"01-Apr-2026", "Bharat Electronics Ltd", reportMoney("118000")}, Indent: 1}},
	}
	got, err := RenderReport(tbl)
	if err != nil {
		t.Fatalf("%v", err)
	}
	ops := reportPagesText(t, got)[0]
	var dates []string
	for _, o := range ops {
		if o.size == reportBodySize && o.x < reportFirstColumnRight(tbl) {
			dates = append(dates, o.text)
		}
	}
	if len(dates) != 1 {
		t.Fatalf("the date was drawn on %d lines (%v). A date split over two lines reads as corrupt data: nobody can tell whether the voucher date is wrong or the print is.", len(dates), dates)
	}
	if !strings.HasSuffix(dates[0], reportEllipsis) {
		t.Errorf("the date printed as %q with no %q, so it reads as a complete but different date instead of as a column that is too narrow", dates[0], reportEllipsis)
	}
	reportAssertNothingOverflowsItsColumn(t, tbl, got)
	reportAssertNoFurnitureIsClippedByTheEdgeOfTheSheet(t, tbl, got)
}

// reportFirstColumnRight is the right edge of the first column, for the test above.
func reportFirstColumnRight(tbl ReportTable) float64 {
	return newReportGeom(tbl, A4Portrait).colX[1]
}

