// TestAStatementWithNoCompanyNameIsRefusedRatherThanPrintedUnattributable is the
// bank's test, not the renderer's. A Balance Sheet is what a lender reads to
// decide whose books it is holding; one with a blank letterhead is a page of
// figures belonging to nobody, and unlike a wrong figure there is nothing on the
// paper that can ever identify it again. Before this check the renderer produced
// exactly that document — signed, paginated, and anonymous — with no refusal and
// no notice.
func TestAStatementWithNoCompanyNameIsRefusedRatherThanPrintedUnattributable(t *testing.T) {
	for _, name := range []string{"", " ", "   ", "\t", "\n", " \t\n "} {
		tbl := reportTrialBalanceFixture()
		tbl.Company.Name = name

		pdf, err := RenderReport(tbl)
		if err == nil {
			t.Fatalf("a Trial Balance whose company name is %q printed %d bytes: every figure on it is attributed to nobody, and a bank, an auditor or an assessing officer holding that sheet cannot say whose statement it is",
				name, len(pdf))
		}
		if pdf != nil {
			t.Errorf("the refusal of an unattributable statement still returned %d bytes of PDF; a caller that ignores the error would write an anonymous Balance Sheet to disk", len(pdf))
		}
		if !errors.Is(err, ErrReportHasNoIssuer) {
			t.Errorf("company name %q was refused as %v, which does not identify itself as ErrReportHasNoIssuer, so no caller can tell this apart from a layout fault", name, err)
		}
		// The 422-not-500 contract. internal/server's writePrintError answers
		// ErrVoucherParticularMissing with 422 and the message verbatim; without
		// this unwrap a missing company name reaches the operator as a 500 with
		// nothing they can act on, for a fault they can fix in the company master.
		if !errors.Is(err, ErrVoucherParticularMissing) {
			t.Errorf("company name %q was refused with an error that does not unwrap to ErrVoucherParticularMissing (%v): the HTTP layer will answer 500 for a company master an operator could fix in a keystroke", name, err)
		}
		if !strings.Contains(err.Error(), "Trial Balance") {
			t.Errorf("the refusal does not say WHICH statement was refused, and a print queue running eight reports gives the operator no way to tell: %v", err)
		}
	}
}

// TestTheTwoRenderersAgreeThatADocumentWithNoIssuerIsNotEvidence pins the
// PRECEDENT rather than one renderer. voucherdoc.go has always refused a receipt
// with no issuer name ("a document with no issuer is not evidence of anything")
// while report.go printed a signed Balance Sheet with a blank letterhead. There is
// no reading of that difference in which the Rs 200 receipt is the document that
// needed protecting, so if a later change relaxes either side, this fails.
func TestTheTwoRenderersAgreeThatADocumentWithNoIssuerIsNotEvidence(t *testing.T) {
	v := vdReceiptFixture()
	v.Supplier.Name = "  "
	if _, err := RenderVoucherDoc(v); err == nil {
		t.Error("a receipt with no issuer name printed; voucherdoc.go's refusal has been lost")
	}

	tbl := reportTrialBalanceFixture()
	tbl.Company.Name = "  "
	if _, err := RenderReport(tbl); err == nil {
		t.Error("a Trial Balance with no company name printed while a receipt with no issuer is refused; the same blank letterhead cannot be fatal on a Rs 200 receipt and acceptable on a statement a bank reads")
	}
}

