func TestTheSameTrialBalanceRendersByteIdenticalEveryTime(t *testing.T) {
	a, err := RenderReport(reportTrialBalanceFixture())
	if err != nil {
		t.Fatalf("%v", err)
	}
	b, err := RenderReport(reportTrialBalanceFixture())
	if err != nil {
		t.Fatalf("%v", err)
	}
	if !bytes.Equal(a, b) {
		t.Fatalf("two renders of the same Trial Balance differ at byte %d, so no golden test in this file proves anything and two prints of one statement are two different documents", reportFirstDiff(a, b))
	}
}

func TestNoRowIsPrintedOverTheColumnHeadersOrOffTheFootOfTheSheet(t *testing.T) {
	for name, tbl := range map[string]ReportTable{
		"Trial Balance": reportTrialBalanceFixture(),
		"Day Book":      reportDayBookFixture(),
		"Outstandings":  reportThreePageFixture(),
	} {
		size := A4Portrait
		if tbl.Landscape {
			size = A4Landscape
		}
		g := newReportGeom(tbl, size)
		got, err := RenderReport(tbl)
		if err != nil {
			t.Fatalf("%s: %v", name, err)
		}
		for pi, ops := range reportPagesText(t, got) {
			for _, o := range ops {
				if o.size != reportBodySize {
					continue
				}
				if o.y > g.firstRowTop {
					t.Errorf("%s page %d: %q is drawn at y=%s, above the column-header rule at y=%s, so it is printed on top of the headers",
						name, pi+1, o.text, fmtNum(o.y), fmtNum(g.firstRowTop))
				}
				if o.y < reportMargin {
					t.Errorf("%s page %d: %q is drawn at y=%s, below the %s-point bottom margin, so it is off the printable area and a printer will drop it",
						name, pi+1, o.text, fmtNum(o.y), fmtNum(reportMargin))
				}
			}
		}
	}
}

func TestTheReportTitleCanBeOverriddenByTheCompanysTemplate(t *testing.T) {
	tbl := reportTrialBalanceFixture()
	tbl.Overrides.Title = "Trial Balance (Management Copy)"
	got, err := RenderReport(tbl)
	if err != nil {
		t.Fatalf("%v", err)
	}
	ops := reportPagesText(t, got)[0]
	if !reportContains(ops, "Trial Balance (Management Copy)") {
		t.Errorf("Overrides.Title was ignored, so a company that renamed its statement still gets the built-in title")
	}
	if reportContains(ops, "Trial Balance") {
		t.Errorf("both the overridden and the built-in title are on the page, so the statement has two titles")
	}
}

// reportAssertNothingOverflowsItsColumn checks the invariant that makes these
// documents readable: every drawn BODY cell stays inside its own column. A cell
// that runs over the next column's edge does not look broken — it looks like the
// neighbouring figure has extra digits in front of it.
func reportAssertNothingOverflowsItsColumn(t *testing.T, tbl ReportTable, pdf []byte) {
	t.Helper()
	size := A4Portrait
	if tbl.Landscape {
		size = A4Landscape
	}
	g := newReportGeom(tbl, size)

	const eps = 0.05
	for pi, ops := range reportPagesText(t, pdf) {
		for _, o := range ops {
			if o.size != reportBodySize {
				// Furniture — the title, the letterhead and the page number are not
				// in any column, so the column test cannot judge them. They are NOT
				// unchecked: reportAssertNoFurnitureIsClippedByTheEdgeOfTheSheet
				// measures them against the sheet instead. This escape used to be the
				// whole check on the letterhead, and a company name too long for the
				// paper went out clipped at both ends of every statement.
				continue
			}
			f := Helvetica
			if o.font == HelveticaBold.resourceName() {
				f = HelveticaBold
			}
			if o.font == HelveticaOblique.resourceName() {
				continue // the empty-report notice is centred across the table
			}
			w := Measure(f, o.size, o.text)
			col := -1
			for i := range tbl.Columns {
				if o.x >= g.colX[i]-eps && o.x < g.colX[i+1]+eps {
					col = i
					break
				}
			}
			if col < 0 {
				t.Errorf("page %d: %q is drawn at x=%s, which is in no column of this table", pi+1, o.text, fmtNum(o.x))
				continue
			}
			limit := g.colX[col+1] - reportCellPad
			if o.x+w > limit+eps {
				t.Errorf("page %d: %q ends at x=%s but column %q ends at x=%s, so it runs into the next column and the figure beside it reads as a longer number than it is",
					pi+1, o.text, fmtNum(o.x+w), tbl.Columns[col].Header, fmtNum(limit))
			}
		}
	}
}

// reportAssertNoFurnitureIsClippedByTheEdgeOfTheSheet checks the FURNITURE — the
// company name, the letterhead lines, the title, the subtitle, the column headers
// and the page number — against the printable width of the sheet.
//
// WHY THIS EXISTS AS A SECOND ASSERTION. The column check above judges a cell
// against its column and has nothing to say about a line that belongs to no
// column, so it skips every operator that is not set at reportBodySize. For one
// wave that skip WAS the letterhead's only test, and it was written down as
// intended ("furniture: the title and the letterhead span the sheet") — with the
// consequence that the company name, drawn by TextCenter with no wrap, could be
// half a sheet wider than the sheet and no test would say so. TextCenter clips a
// long line at BOTH ENDS, so the failure mode is a statement whose letterhead
// reads "ering & Fabrication Works Priv": still plausible, still signed, and
// naming a business that does not exist.
//
// EVERY drawn string is checked, at every size, so nothing on the page can be
// added later that quietly falls outside both assertions.
func reportAssertNoFurnitureIsClippedByTheEdgeOfTheSheet(t *testing.T, tbl ReportTable, pdf []byte) {
	t.Helper()
	size := A4Portrait
	if tbl.Landscape {
		size = A4Landscape
	}
	g := newReportGeom(tbl, size)

	const eps = 0.05
	for pi, ops := range reportPagesText(t, pdf) {
		for _, o := range ops {
			w := Measure(reportFontNamed(o.font), o.size, o.text)
			role := reportFurnitureRole(o.size)
			if o.x < g.tableLeft-eps {
				t.Errorf("page %d of the %s: %s (%q) starts at x=%s, left of the printable left edge at x=%s, so %s points of it are off the LEFT edge of the paper — a centred line wider than the sheet is clipped at BOTH ends, and the words that survive name something other than what the books say",
					pi+1, tbl.Title, role, o.text, fmtNum(o.x), fmtNum(g.tableLeft), fmtNum(g.tableLeft-o.x))
			}
			if o.x+w > g.tableRight+eps {
				t.Errorf("page %d of the %s: %s (%q) is %s points wide and ends at x=%s, past the printable right edge at x=%s, so %s points of it are off the RIGHT edge of the paper",
					pi+1, tbl.Title, role, o.text, fmtNum(w), fmtNum(o.x+w), fmtNum(g.tableRight), fmtNum(o.x+w-g.tableRight))
			}
		}
	}
}

// reportFurnitureRole names what a drawn string IS, from the size it was set at,
// so a failure says "the company's own name" rather than "an operator".
func reportFurnitureRole(size float64) string {
	switch size {
	case reportCompanySize:
		return "the company's own name in the letterhead"
	case reportTitleSize:
		return "the report title"
	case reportSubtitleSize:
		return "the period line under the title"
	case reportBodySize:
		return "a body cell"
	case reportLetterheadSize:
		// reportLetterheadSize, reportColHeaderSize and reportPageNumSize are all
		// 8pt, so this one label covers the three of them rather than claiming to
		// tell them apart.
		return "a letterhead line, a column header or the page number"
	}
	return "a drawn line"
}

// reportFontNamed maps a /F<n> resource name back to the Font it was drawn with,
// walking allFonts so a font added to the package cannot silently be measured as
// Helvetica here.
func reportFontNamed(resource string) Font {
	for _, f := range allFonts {
		if f.resourceName() == resource {
			return f
		}
	}
	return Helvetica
}

// TestTheCompanysOwnNameWrapsAcrossTheLetterheadInsteadOfBeingClippedOffBothEdgesOfTheSheet
// is the letterhead's own overflow test. A co-operative society's registered name
// really is this long, and the letterhead is the line a bank reads to decide whose
// Balance Sheet it is holding.
func TestTheCompanysOwnNameWrapsAcrossTheLetterheadInsteadOfBeingClippedOffBothEdgesOfTheSheet(t *testing.T) {
	const long = "Shri Mahalaxmi Engineering & Fabrication Works Private Limited (Bhiwandi and Wada Units)"
	company := reportTestCompany()
	company.Name = long
	tbl := ReportTable{
		Title:    "Balance Sheet",
		Subtitle: "as at 31-Mar-2027",
		Company:  company,
		Columns: []Column{
			{Header: "Particulars", Align: AlignLeft, Width: 4},
			{Header: "Amount", Align: AlignRight, Width: 1.5},
		},
		Rows: []Row{
			{Cells: []string{"Capital Account"}, Bold: true},
			{Cells: []string{"Share Capital", reportMoney("2500000")}, Indent: 1},
		},
		Footer: []Row{{Cells: []string{"Total", reportMoney("2500000")}, Bold: true, RuleAbove: true}},
	}

	got, err := RenderReport(tbl)
	if err != nil {
		t.Fatalf("a Balance Sheet for a company with a long registered name would not print at all: %v", err)
	}

	if Measure(HelveticaBold, reportCompanySize, long) <= A4Portrait.Width-2*reportMargin {
		t.Fatalf("this fixture no longer proves anything: %q measures %s points and the printable width is %s, so it never needed to wrap",
			long, fmtNum(Measure(HelveticaBold, reportCompanySize, long)), fmtNum(A4Portrait.Width-2*reportMargin))
	}

	// The invariant first, because it is the one that states the damage.
	reportAssertNoFurnitureIsClippedByTheEdgeOfTheSheet(t, tbl, got)
	reportAssertNothingOverflowsItsColumn(t, tbl, got)

	ops := reportPagesText(t, got)[0]
	if reportContains(ops, long) {
		t.Errorf("the company's registered name was drawn as ONE line wider than the sheet; TextCenter clips it at both ends, so the Balance Sheet goes out under a name that is not the company's")
	}

	// Nothing was lost in the wrapping: a letterhead missing "Private Limited" names
	// a different legal person from the one whose books these are.
	var letterhead []reportTextOp
	for _, o := range ops {
		if o.size == reportCompanySize {
			letterhead = append(letterhead, o)
		}
	}
	if len(letterhead) < 2 {
		t.Fatalf("the letterhead was drawn on %d line(s); a name that needs %s points on a %s-point sheet has to wrap", len(letterhead), fmtNum(Measure(HelveticaBold, reportCompanySize, long)), fmtNum(A4Portrait.Width-2*reportMargin))
	}
	joined := ""
	for _, o := range letterhead {
		joined += o.text + " "
	}
	for _, word := range strings.Fields(long) {
		if !strings.Contains(joined, word) {
			t.Errorf("the wrapped letterhead lost %q; it now prints %q, which is not the name of the company whose Balance Sheet this is", word, strings.TrimSpace(joined))
		}
	}

	// The extra letterhead line pushed the title down with it. If letterheadBottom
	// did not count the wrapped lines, the title would be struck through the second
	// line of the company's name.
	lowestName := letterhead[0].y
	for _, o := range letterhead {
		if o.y < lowestName {
			lowestName = o.y
		}
	}
	titleY := 0.0
	for _, o := range ops {
		if o.size == reportTitleSize && o.text == "Balance Sheet" {
			titleY = o.y
		}
	}
	if titleY == 0 {
		t.Fatalf("the Balance Sheet has no title on it")
	}
	if titleY >= lowestName-reportTitleSize {
		t.Errorf("the title is drawn at y=%s and the last line of the company name at y=%s, so the title is printed through the letterhead: the two blocks overlap and both become unreadable",
			fmtNum(titleY), fmtNum(lowestName))
	}
}

// TestALongClosingNoteWrapsInsteadOfRunningOffBothEdgesOfTheLastSheet is the same
// defect in the other half of the same block: Overrides.FooterLines is a company's
// own text, centred, and its reserve is counted in baselines.
func TestALongClosingNoteWrapsInsteadOfRunningOffBothEdgesOfTheLastSheet(t *testing.T) {
	tbl := reportTrialBalanceFixture()
	tbl.Overrides.HeaderLines = []string{
		"Registered Office: 14, Nariman Point, Mumbai 400021 - GSTIN 27AABCS1429B1ZX - Tel 022 2202 1188 - E-Mail accounts@sundaramtraders.example - CIN U51909MH1998PTC114455",
	}
	tbl.Overrides.FooterLines = []string{
		"This statement is prepared from the books of account and is subject to confirmation by the parties named in it; balances shown against a party include bills not yet due for payment as at the date of this statement.",
	}
	got, err := RenderReport(tbl)
	if err != nil {
		t.Fatalf("%v", err)
	}
	reportAssertNothingOverflowsItsColumn(t, tbl, got)
	reportAssertNoFurnitureIsClippedByTheEdgeOfTheSheet(t, tbl, got)

	// And every word of both survived the wrap.
	joined := strings.Join(reportPageStrings(reportPagesText(t, got)[len(reportPagesText(t, got))-1]), " ")
	for _, word := range []string{"CIN", "U51909MH1998PTC114455", "confirmation", "statement."} {
		if !strings.Contains(joined, word) {
			t.Errorf("the wrapped letterhead or closing note lost %q, so the note the company chose to print is not the note that printed", word)
		}
	}
}
